# dash.<relation> -> the date/time columns it actually exposes.
DASH_DATE_COLUMNS: dict[str, frozenset[str]] = {
    f"dash.{rel}": frozenset(
        col for col, dtype in cols.items() if dtype in DATE_TYPES
    )
    for rel, cols in DASH_COLUMNS.items()
}
